@namespace sv_caa98a3263484540a5be40d957810449.Components.Pages.Board

<div class="task-card">
    <h4>@Task.Title</h4>
    <p class="assignee">@Task.Assignee</p>
    <span class="priority-badge @GetPriorityClass()">@Task.Priority</span>
    <span class="due-date">@Task.DueDate.ToString("MMM dd")</span>
    <div class="card-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn-move" @onclick="() => OnMoveLeft.InvokeAsync(Task)">← Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn-move" @onclick="() => OnMoveRight.InvokeAsync(Task)">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveRight { get; set; }

    private string GetPriorityClass() => Task.Priority switch
    {
        "High" => "priority-high",
        "Medium" => "priority-medium",
        "Low" => "priority-low",
        _ => ""
    };
}

@namespace sv_caa98a3263484540a5be40d957810449.Components.Pages.Board

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="Save">Save</button>
        <button class="btn-cancel" @onclick="Cancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnSave { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private string title = "";
    private string assignee = "";
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private async Task Save()
    {
        if (!string.IsNullOrWhiteSpace(title))
        {
            await OnSave.InvokeAsync((title, assignee, priority, dueDate));
            title = "";
            assignee = "";
            priority = "Medium";
            dueDate = DateTime.Today.AddDays(7);
        }
    }

    private async Task Cancel()
    {
        await OnCancel.InvokeAsync();
    }
}

@namespace sv_caa98a3263484540a5be40d957810449.Components.Pages.Board

<div class="board-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="task-count">@Tasks.Count</span>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="OnMoveLeft"
                      OnMoveRight="OnMoveRight" />
        }
    </div>
    <div class="column-footer">
        @if (showForm)
        {
            <AddTaskForm OnSave="HandleSave" OnCancel="() => showForm = false" />
        }
        else
        {
            <button class="btn-add" @onclick="() => showForm = true">+ Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = "";
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveRight { get; set; }
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnAddTask { get; set; }

    private bool showForm;

    private async Task HandleSave((string Title, string Assignee, string Priority, DateTime DueDate) formData)
    {
        await OnAddTask.InvokeAsync(formData);
        showForm = false;
    }
}

@namespace sv_caa98a3263484540a5be40d957810449.Components.Pages.Board

<div class="stats-bar">
    <div class="stat-item">
        <span class="stat-label">Total</span>
        <span class="stat-value">@TotalCount</span>
    </div>
    <div class="stat-item">
        <span class="stat-label">To Do</span>
        <span class="stat-value">@ToDoCount</span>
    </div>
    <div class="stat-item">
        <span class="stat-label">In Progress</span>
        <span class="stat-value">@InProgressCount</span>
    </div>
    <div class="stat-item">
        <span class="stat-label">Done</span>
        <span class="stat-value">@DoneCount</span>
    </div>
    <div class="stat-item stat-overdue">
        <span class="stat-label">Overdue</span>
        <span class="stat-value">@OverdueCount</span>
    </div>
</div>

@code {
    [Parameter] public int TotalCount { get; set; }
    [Parameter] public int ToDoCount { get; set; }
    [Parameter] public int InProgressCount { get; set; }
    [Parameter] public int DoneCount { get; set; }
    [Parameter] public int OverdueCount { get; set; }
}

@namespace sv_caa98a3263484540a5be40d957810449.Components.Pages.Board

<div class="search-bar">
    <input type="text" placeholder="Search tasks by title..." value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = "";
    [Parameter] public EventCallback<string> OnSearchChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? "");
    }
}

@page "/board"
@namespace sv_caa98a3263484540a5be40d957810449.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (loading)
{
    <p class="loading">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error">@errorMessage</p>
}
else
{
    <BoardStatsBar TotalCount="allTasks.Count"
                   ToDoCount="GetTasksByStatus("To Do").Count"
                   InProgressCount="GetTasksByStatus("In Progress").Count"
                   DoneCount="GetTasksByStatus("Done").Count"
                   OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="board-columns">
        <BoardColumn ColumnName="To Do"
                     Tasks="GetFilteredTasksByStatus("To Do")"
                     ShowMoveLeft="false"
                     ShowMoveRight="true"
                     OnMoveRight="task => MoveTask(task, "In Progress")"
                     OnAddTask="data => AddTask(data, "To Do")" />

        <BoardColumn ColumnName="In Progress"
                     Tasks="GetFilteredTasksByStatus("In Progress")"
                     ShowMoveLeft="true"
                     ShowMoveRight="true"
                     OnMoveLeft="task => MoveTask(task, "To Do")"
                     OnMoveRight="task => MoveTask(task, "Done")"
                     OnAddTask="data => AddTask(data, "In Progress")" />

        <BoardColumn ColumnName="Done"
                     Tasks="GetFilteredTasksByStatus("Done")"
                     ShowMoveLeft="true"
                     ShowMoveRight="false"
                     OnMoveLeft="task => MoveTask(task, "In Progress")"
                     OnAddTask="data => AddTask(data, "Done")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = "";
    private bool loading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private List<TaskItem> GetTasksByStatus(string status) =>
        allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredTasksByStatus(string status) =>
        allTasks
            .Where(t => t.Status == status)
            .Where(t => string.IsNullOrEmpty(searchText) ||
                        t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase))
            .ToList();

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task AddTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to add task: {ex.Message}";
        }
    }
}

